function eb.upgradeGain(CCb,DCb,ECb,FCb,GCb,HCb)
local ICb,JCb=DCb[ECb],DCb[ECb+1]
local KCb=(ICb.cd>0 and ICb.damage/ICb.cd or 0)
local LCb=(JCb.cd>0 and JCb.damage/JCb.cd or 0)*V.aoe(JCb.atk,JCb.range)/math.max(0.3,V.aoe(ICb.atk,ICb.range))
local MCb=KCb>0 and CCb*(LCb/KCb-1)or(HCb or 0)
local NCb=DCb[ECb+2]
if NCb and ECb+1<DCb.max and NCb.cd>0 and JCb.cd>0 and KCb>0 then
local OCb=CCb*((NCb.damage/NCb.cd)/KCb-1)
local PCb=FCb+NCb.cost*GCb
if OCb/PCb>MCb/FCb then
MCb=MCb+(OCb/PCb*FCb-MCb)*0.5
end
end
local QCb=(JCb.range or 0)>(ICb.range or 0)and(1+((JCb.range-ICb.range)/math.max(1,ICb.range)))or 1
return math.max(0,MCb)*QCb
end
