end
jb.note(string.format(_se[4083],jmc,kmc,dmc and _se[4084]or(hmc<=1 and _se[4085]or _se[4086]),jb.luck(cmc),(tonumber(N.cur(_se[2171]))or 0)-mmc))
local Gmc,Hmc,Imc=jb.res(jb.data())
