function bb.buildPath()
bb.samples={}
local Nqc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Nqc then
return
end
for Oqc,Pqc in pairs(Nqc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Oqc.Name])then
local Qqc={}
for Rqc,Sqc in ipairs(Pqc.points or{})do
table.insert(Qqc,Sqc.part.Position)
end
local Tqc=0
for Uqc=2,#Qqc do
Tqc=Tqc+(Qqc[Uqc]-Qqc[Uqc-1]).Magnitude
end
local Vqc=0
for Wqc=2,#Qqc do
local Xqc,Yqc=Qqc[Wqc-1],Qqc[Wqc]
local Zqc=(Yqc-Xqc).Magnitude
local _qc=math.max(1,math.floor(Zqc/2))
for arc=0,_qc-1 do
local brc=Xqc:Lerp(Yqc,arc/_qc)
table.insert(bb.samples,{pos=brc,prog=(Vqc+Zqc*arc/_qc)/math.max(1,Tqc),lane=Oqc.Name})
end
Vqc=Vqc+Zqc
end
if Qqc[#Qqc]then
table.insert(bb.samples,{pos=Qqc[#Qqc],prog=1,lane=Oqc.Name})
end
end
end
pcall(bb.readHidden,Nqc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local crc=tonumber(bb.ld and bb.ld._portal_lanes)
local drc=gb.laneList(bb.samples)
if crc and crc>=1 and drc and#drc>crc then
bb.laneWant=crc
end
bb.laneTotal=drc and#drc or 1
bb.countLanes()
