function bb.readHidden(erc)
local frc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(frc)~=_se[2106]or not next(frc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local grc
for hrc,irc in pairs(erc)do
if frc[hrc.Name]and type(irc.points)==_se[2106]and#irc.points>=2 then
local jrc={}
for krc,lrc in ipairs(irc.points)do
jrc[krc]=U.flat(lrc.part.Position)
end
local mrc={}
for nrc,orc in ipairs(bb.samples)do
local prc=tostring(orc.lane)
mrc[prc]=mrc[prc]or{}
table.insert(mrc[prc],orc)
end
local qrc,rrc
for trc,urc in pairs(mrc)do
local vrc=0
for wrc=1,#jrc,math.max(1,math.floor(#jrc/20))do
local xrc=math.huge
for yrc,zrc in ipairs(urc)do
local Arc=(U.flat(zrc.pos)-jrc[wrc]).Magnitude
if Arc<xrc then
xrc=Arc
end
end
vrc=vrc+xrc
end
if not rrc or vrc<rrc then
qrc,rrc=trc,vrc
end
end
local Brc,Crc,Drc,Erc,Frc,Grc={},nil,nil,nil,0,0
for Hrc,Irc in ipairs(jrc)do
local Jrc,Krc=nil,math.huge
for Lrc,Mrc in ipairs(mrc[qrc])do
local Nrc=(U.flat(Mrc.pos)-Irc).Magnitude
if Nrc<Krc then
Krc,Jrc=Nrc,Mrc.prog
end
end
Grc=math.max(Grc,Krc)
if Drc then
local Orc=Jrc-Drc
local Prc=(Orc>0.002 and 1)or(Orc< -0.002 and-1)or Erc
if Erc and Prc and Prc~=Erc then
table.insert(Brc,math.floor(Drc*1000+0.5)/1000)
end
Erc,Frc=Prc or Erc,Frc+math.abs(Orc)
else
Crc=Jrc
end
Drc=Jrc
if Hrc%50==0 then
task.wait()
end
end
if Drc and Grc<=8 then
table.insert(Brc,math.floor(Drc*1000+0.5)/1000)
grc=grc or{}
grc[hrc.Name]={from=math.floor((Crc or 0)*1000+0.5)/1000,len=math.floor(Frc*1000+0.5)/1000,turns=Brc,road=qrc}
end
end
end
if not grc then
return
end
local Qrc=bb.ld.map
P.maps[Qrc]=P.maps[Qrc]or{}
local Rrc=P.maps[Qrc].hidden
P.maps[Qrc].hidden=grc
if type(Rrc)~=_se[2106]then
for Src,Trc in pairs(grc)do
F.log(1,_se[2775],string.format(_se[4176],Src,Trc.len,tostring(Trc.road),math.floor((#Trc.turns-1)/2)))
end
F.saveSoon()
end
end
