return false
end
local Tid=((tonumber(Qid.base)or 0)-(tonumber(Rid.base)or 0))/Sid
if Tid<=0 or(tonumber(Rid.base)or 0)<=0 then
return false
end
local Uid=Rid.base/Tid
local Vid,Wid=0,0
local Xid,Yid=Qid.foes or{},Rid.foes or{}
for Zid,ajd in pairs(Yid)do
if ajd.prog>=bb.BASE_END then
Vid=Vid+ajd.hp
local bjd=Xid[Zid]
if bjd then
Wid=Wid+math.max(0,bjd.hp-ajd.hp)
end
end
end
for cjd,djd in pairs(Xid)do
if djd.prog>=bb.BASE_END and not Yid[cjd]then
Wid=Wid+djd.hp
end
end
if Vid<=0 then
return false
end
local ejd=Wid/Sid
local fjd=ejd>0 and Vid/ejd or math.huge
local gjd={baseTime=Uid,loss=Tid,atEnd=Vid,rate=ejd,killTime=fjd}
return Uid<bb.BASE_SOON and fjd>Uid*bb.BASE_MARGIN,gjd
end
