end
for OCd,PCd in ipairs({2,5,10})do
local QCd={}
for RCd,SCd in ipairs(MCd.waves or{})do
if RCd%PCd==0 or RCd== #MCd.waves then
table.insert(QCd,SCd)
end
end
MCd.waves=QCd
NCd=U.json(MCd)
if#NCd<=3900 then
return NCd
end
end
for TCd,UCd in ipairs(MCd.placed or{})do
UCd.why=nil
end
NCd=U.json(MCd)
if#NCd<=3900 then
return NCd
end
if MCd.mapData then
MCd.mapData.dens=nil
end
NCd=U.json(MCd)
if#NCd<=3900 then
return NCd
end
MCd.placed,MCd.plan=nil,nil
NCd=U.json(MCd)
if#NCd<=3900 then
return NCd
end
MCd.settings=nil
NCd=U.json(MCd)
if#NCd<=3900 then
return NCd
end
MCd.learn=nil
return U.json(MCd):sub(1,3900)
end
